#include <gtest/gtest.h>

#include <sstream>
#include <string>

#include <swrm_flocking_core/utilities.hpp>
#include <swrm_flocking_core/types.hpp>

TEST(TestUtilities, TestingTest) {
    testing::internal::CaptureStdout();
    hpscalar value = 3.;
    print_hpscalar(value);
    std::string output = testing::internal::GetCapturedStdout();
    std::ostringstream oss;
    oss << std::setprecision(HP_PRECISION) << value << std::endl;
    std::string expected_output = oss.str();

    EXPECT_EQ(output, expected_output);
}
